-- Era corrections for NPC level and HP, from a ShowEQ capture of the live servers in 2000-2002
-- (Kunark/Velious era): tools/npc_stats/EQSpawns-showeq-2002.txt, the list Project 1999 used,
-- archived at web.archive.org/web/20021129210131/http://www.geocities.com/ficticiousname9/.
--
-- Checked against 8,325 spawned NPCs that took Quarm values in patch 004: Quarm's HP is within 5%
-- of the capture for 91% of them (the original EQClassic DB: 38%), which validates 004 for HP. The
-- exceptions are Quarm-specific choices (e.g. Neriak NPCs made unkillable at level 61 / 2,000,000 HP,
-- captured at level 30 / 1,150 HP). This patch clamps level and HP of the 1231 spawned NPCs that fall
-- outside the captured range (HP tolerance 5%) back into that range. NPCs are matched by normalised
-- name + zone. Absolute values: running it twice is harmless. Apply after 004.
DROP TEMPORARY TABLE IF EXISTS npc_era_fix;
CREATE TEMPORARY TABLE npc_era_fix (id int(11) NOT NULL PRIMARY KEY, level int(11) NOT NULL, hp int(11) NOT NULL);

UPDATE npc_types o JOIN npc_era_fix f ON f.id = o.id SET o.level = f.level, o.hp = f.hp;
UPDATE npc_types_without o JOIN npc_era_fix f ON f.id = o.id SET o.level = f.level, o.hp = f.hp;
DROP TEMPORARY TABLE npc_era_fix;
